-- Policies and Help for the November features (src/data/legalPages.json has the same):
-- the Privacy Policy and the Children's Privacy Notice name moods and pace, bedtime, Translate,
-- content notes and audio clips; Help gets a bedtime paragraph and a section on Didn't finish,
-- rereads, moods, content notes, Translate, clips and buddy reads. Each change applies only where
-- the text is still the built-in wording, so an editor's rewording is left as it is.

update public.legal_pages set sections = replace(sections::text, $lw$Anthropic (Claude) writes book summaries, answers Ask the book questions, writes Who's who and writes chapter quizzes and Previously… recaps (see section 6).$lw$, $lw$Anthropic (Claude) writes book summaries and content notes, answers Ask the book questions, translates passages you select, writes Who's who and writes chapter quizzes and Previously… recaps (see section 6).$lw$)::jsonb, updated_at = now()
where slug = $lw$privacy$lw$ and strpos(sections::text, $lw$Anthropic (Claude) writes book summaries, answers Ask the book questions, writes Who's who and writes chapter quizzes and Previously… recaps (see section 6).$lw$) > 0;
update public.legal_pages set sections = replace(sections::text, $lw$from the book's details; no personal information is sent. Ask the book:$lw$, $lw$from the book's details; no personal information is sent. Content notes: for each of our titles, how much violence, death, frightening scenes, language, sexual content, alcohol and drugs, prejudice and self-harm it has, written the first time anyone asks, from the book's details; no personal information is sent, and the notes are kept so everyone sees the same ones. Ask the book:$lw$)::jsonb, updated_at = now()
where slug = $lw$privacy$lw$ and strpos(sections::text, $lw$from the book's details; no personal information is sent. Ask the book:$lw$) > 0;
update public.legal_pages set sections = replace(sections::text, $lw$we don't send your name, email or account details. Who's who:$lw$, $lw$we don't send your name, email or account details. Translate: a passage you select in a public-domain book, in another language. We send only the words you selected (they must be in that chapter), nothing about you, and keep nothing. Who's who:$lw$)::jsonb, updated_at = now()
where slug = $lw$privacy$lw$ and strpos(sections::text, $lw$we don't send your name, email or account details. Who's who:$lw$) > 0;
update public.legal_pages set sections = replace(sections::text, $lw$Ask the book and Who's who aren't offered to Kids profiles; quizzes are. Summaries, answers, Who's who and quizzes are labelled as written by AI.$lw$, $lw$Ask the book, Translate and Who's who aren't offered to Kids profiles; summaries, content notes, recaps and quizzes are. Summaries, content notes, answers, translations, Who's who, recaps and quizzes are labelled as written by AI.$lw$)::jsonb, updated_at = now()
where slug = $lw$privacy$lw$ and strpos(sections::text, $lw$Ask the book and Who's who aren't offered to Kids profiles; quizzes are. Summaries, answers, Who's who and quizzes are labelled as written by AI.$lw$) > 0;
update public.legal_pages set sections = replace(sections::text, $lw$daily limit, weekly goal and player settings, and whether it's set aside.$lw$, $lw$daily limit, weekly goal, bedtime and wake-up time (Kids profiles) and player settings, and whether it's set aside.$lw$)::jsonb, updated_at = now()
where slug = $lw$privacy$lw$ and strpos(sections::text, $lw$daily limit, weekly goal and player settings, and whether it's set aside.$lw$) > 0;
update public.legal_pages set sections = replace(sections::text, $lw$your private reading journal (dated entries about a book that only your account sees), ratings, favourites and lists,$lw$, $lw$your private reading journal (dated entries about a book that only your account sees), ratings, the moods and pace you tag books with, favourites and lists,$lw$)::jsonb, updated_at = now()
where slug = $lw$privacy$lw$ and strpos(sections::text, $lw$your private reading journal (dated entries about a book that only your account sees), ratings, favourites and lists,$lw$) > 0;
update public.legal_pages set sections = replace(sections::text, $lw$(a CSV of your books, shelves, star ratings and dates); we don't send them to either site.$lw$, $lw$(a CSV of your books, shelves, star ratings, dates, and the moods and pace you tagged); we don't send them to either site. Audio clips you share are links to a stretch of a public-domain LibriVox recording, played from the Internet Archive; we don't record or keep them, or who shared them.$lw$)::jsonb, updated_at = now()
where slug = $lw$privacy$lw$ and strpos(sections::text, $lw$(a CSV of your books, shelves, star ratings and dates); we don't send them to either site.$lw$) > 0;
update public.legal_pages set sections = replace(sections::text, $lw$and any daily reading limit and weekly reading goal you set.$lw$, $lw$and any daily reading limit, weekly reading goal and bedtime you set.$lw$)::jsonb, updated_at = now()
where slug = $lw$childrens-privacy$lw$ and strpos(sections::text, $lw$and any daily reading limit and weekly reading goal you set.$lw$) > 0;
update public.legal_pages set sections = replace(sections::text, $lw$its Up next queue, ratings, favourites and lists,$lw$, $lw$its Up next queue, ratings, the moods and pace it tags books with, favourites and lists,$lw$)::jsonb, updated_at = now()
where slug = $lw$childrens-privacy$lw$ and strpos(sections::text, $lw$its Up next queue, ratings, favourites and lists,$lw$) > 0;
update public.legal_pages set sections = replace(sections::text, $lw$ask the book's AI assistant or use Who's who.$lw$, $lw$ask the book's AI assistant, translate passages or use Who's who.$lw$)::jsonb, updated_at = now()
where slug = $lw$childrens-privacy$lw$ and strpos(sections::text, $lw$ask the book's AI assistant or use Who's who.$lw$) > 0;
update public.legal_pages set sections = replace(sections::text, $lw$can read AI-written book summaries, hear a recap$lw$, $lw$can read AI-written book summaries and content notes, hear a recap$lw$)::jsonb, updated_at = now()
where slug = $lw$childrens-privacy$lw$ and strpos(sections::text, $lw$can read AI-written book summaries, hear a recap$lw$) > 0;
update public.legal_pages set sections = replace(sections::text, $lw$The summaries, recaps and quizzes are kept$lw$, $lw$The summaries, content notes, recaps and quizzes are kept$lw$)::jsonb, updated_at = now()
where slug = $lw$childrens-privacy$lw$ and strpos(sections::text, $lw$The summaries, recaps and quizzes are kept$lw$) > 0;
update public.legal_pages set sections = replace(sections::text, $lw$change its daily limit, weekly goal and age rating,$lw$, $lw$change its daily limit, weekly goal, bedtime and age rating,$lw$)::jsonb, updated_at = now()
where slug = $lw$childrens-privacy$lw$ and strpos(sections::text, $lw$change its daily limit, weekly goal and age rating,$lw$) > 0;
update public.legal_pages set sections = $lw$[{"heading": "Where do the books come from?", "paragraphs": ["LiteraryWorm uses the Google Books API to show book details and covers when you browse and search, so you can find almost any book, save it to your library and write about it.", "The books you can read and listen to in full are public-domain classics: texts from Project Gutenberg and recordings from LibriVox. Other LiteraryWorm titles show sample pages."]}, {"heading": "Can I read my own books?", "paragraphs": ["Yes. In My Library → Uploads, add EPUBs you own that have no DRM: up to 20 at a time, each up to 50 MB (a profile keeps up to 50). For example, buy a book that the publisher sells DRM-free on Google Play Books, download its EPUB from your Google Play Books library, then upload it to LiteraryWorm. Many publishers and stores sell DRM-free books, and public-domain EPUBs are free from Project Gutenberg and Standard Ebooks.", "Your upload opens in the reader with your place, bookmarks and highlights, and once you've opened it on a device, it keeps working there if your connection drops. Books with DRM can't be uploaded, and removing DRM to upload a book isn't allowed (see the Terms of Service)."]}, {"heading": "Reading and listening", "paragraphs": ["Open a book from its page with Read or Listen. Your place is shared between the two and across your devices. The mini-player keeps a book playing while you browse, and its controls also work from your lock screen and headphones.", "To read or listen without a connection, choose Read offline on a public-domain book's page. Each book's page has My journal for private, dated notes only you see; they're exported with your highlights from My Library → Notes. Words you keep from the dictionary come back for review in My words, after 1, 3, 7, 14, 30 and 60 days while you know them. Your reading streak has two rest days a month, used automatically when you miss a day."]}, {"heading": "Your account and household", "paragraphs": ["Each person at home can have their own profile, with its own library and recommendations. Lock a profile with a PIN, set daily limits for younger readers, and change your plan, password or emails in Account. You can cancel or pause online at any time.", "In Account → Sign-in you can add a passkey to log in with your face, fingerprint, screen lock or a security key instead of your password, and rename or remove passkeys you no longer use.", "A Kids profile can ask for a book that isn't on its shelf; a grown-up says yes or no in Account → Family with the account password, and a yes opens that one book for that profile.", "A grown-up can give a Kids profile a bedtime in its profile editor, with the account password: from 7pm to 10pm, and when reading starts again in the morning. Between them, on that device's clock, books and audiobooks show Time for bed and the place is saved; the password allows 15 more minutes.", "Your plan includes some hours of audiobooks a month for the household (Premium has no limit) and a number of devices that can keep books offline. Account → Plan and billing shows how much you've used this month and which devices hold offline places, and lets you free one.", "To hear when a book you set Remind me on comes out, turn on Notifications on this device in Account → Preferences. Once it's on, choose there which notifications you get: books you're waiting for, club meetings, new club posts up to your chapter, an evening streak nudge, and answers to Kids book requests. On iPhone and iPad, add LiteraryWorm to your Home Screen first (Share, then Add to Home Screen) and turn them on in the app.", "Grown-up and teen profiles can put a book on the family shelf from its page; it shows on Home for everyone at home, and Kids profiles see only the books their rating already allows.", "On a book club's page, Where everyone is shows the chapter each member has reached, for members who turn on Show my place to this club; it's off until you turn it on.", "Under a club's discussion, Shared highlights shows passages members marked in the book; ones from chapters you haven't reached stay hidden until you choose to see them. Share one of yours from the list there, with or without its note, and stop sharing it whenever you like.", "My Library → Smart lists fill themselves: Almost there (past halfway), Waiting for you (started, not opened for 30 days), From authors you follow and Loved it.", "A book's page shows Your time with this book once you've read or listened to it: time spent, the days, your pace through it and your biggest days.", "In the player (and the mini-player's More), Previously… catches you up on a public-domain book from the second chapter on: the story so far and the last chapter, written by AI from the chapters before yours only.", "My Library → Notes has Review for highlights: each comes back the day after you make it, then after 1, 3, 7, 14, 30 and 60 days while it still matters, up to 10 a day, and Home says when some are due.", "On a book's page, Reading plan lets you pick a day to finish by: it works out about how many minutes (at your own pace) or pages a day get you there, and says whether you're on track, ahead or behind; Home lists your plans.", "When you buy a gift on Gifts, you can add up to 10 LiteraryWorm books to it (find a title, or add one of your lists); they're waiting in the recipient's library when they redeem it.", "To take your library elsewhere, choose Export for Goodreads or Export for StoryGraph in My Library: you get a CSV of your books, shelves, star ratings (Love it 5, Like it 4, Not for me 2) and dates, made on your device, to import there.", "In the reader, Display has OpenDyslexic among the fonts, and Reading guide: a reading ruler on one line, or line focus, which dims everything but three lines. It follows your pointer or a tap; J and K move it down or up a line.", "On an audiobook's page, Read offline has Listen offline on a schedule: this device keeps the chapter you're on and the next 1, 3, 5 or 10 as you listen, on Wi-Fi only if you like, and can remove chapters you've finished. It counts as one of your plan's offline devices."]}, {"heading": "Your library, moods and more", "paragraphs": ["A book's status can be Want to read, Reading, Finished or Didn't finish, for a book you put down; Didn't finish has its own tab in My Library, and recommendations stop suggesting books like it.", "To read a finished book again, choose Read again on its page. It goes back to Reading from the start, and finishing it again counts as another read, so the page says Your 2nd read or Read twice. Exports for Goodreads and StoryGraph carry the read count and dates.", "Under How did it feel? on a book's page, tag up to three moods, such as funny, hopeful, dark or tense, and a pace. My Library can show the books with one mood, and the Feel-good picks smart list gathers the cheerful ones.", "Each LiteraryWorm title's page has Content notes, written by AI: how much violence, death, frightening scenes, language, sexual content, alcohol and drugs, prejudice and self-harm it has, without spoilers. Grown-ups see them under a Kids profile's book requests too. They can miss things, so check anything that matters to you.", "In a public-domain book, select some words and choose Translate to read them in English, French, German, Spanish, Italian, Portuguese or Dutch. Only the words you selected are sent. Not on Kids profiles.", "In the player, or the mini-player's More menu, Share a clip makes a link to the last 15, 30 or 60 seconds you heard of a LibriVox recording. Anyone with the link can play that stretch.", "To read a book with one friend, choose Read with a friend on its page. A buddy read is a book club for two: send your friend its code, and you get spoiler-safe posts by chapter, meetings and shared highlights."]}, {"heading": "Trouble logging in?", "paragraphs": ["If Log in or Log in with a passkey does nothing, check that your browser isn't letting LiteraryWorm access your local network. LiteraryWorm never needs that permission, and allowing it can stop logging in from working. In Chrome and Edge, select the icon beside the address, choose Site settings, set Local network access to Block, then reload the page and log in again. If your browser asks whether LiteraryWorm can find devices on your local network, choose Block.", "Still stuck? Try a private or incognito window. If that works, a browser extension or something saved in your usual window is in the way. Otherwise, email support@literaryworm.com with your device and browser."]}, {"heading": "Book clubs on your own books", "paragraphs": ["A club can read a LiteraryWorm title or a book you uploaded, such as a DRM-free EPUB you bought. When you start a club in My Library → Clubs, choose LiteraryWorm books or My uploads under Book from, then find the book by title, author or ISBN (an ISBN is looked up on Google Books and matched by title and author). Sort the list by title, author, numbers first or series in reading order, and filter it to one series.", "Uploads stay private, so members don't get your file. The club shows the book's title and author, and each member uploads their own copy and chooses it on the club's page (Choose your copy). Posts, where everyone is and shared highlights then follow each member's place in their own copy, so nothing past their chapter is spoiled. An uploaded book has no recording, so there's no listening along."]}, {"heading": "Report a problem", "paragraphs": ["Tell us what you were doing, the page you were on, and your device and browser, by email to support@literaryworm.com."]}]$lw$::jsonb, updated_at = now()
where slug = $lw$help$lw$ and sections = $lw$[{"heading": "Where do the books come from?", "paragraphs": ["LiteraryWorm uses the Google Books API to show book details and covers when you browse and search, so you can find almost any book, save it to your library and write about it.", "The books you can read and listen to in full are public-domain classics: texts from Project Gutenberg and recordings from LibriVox. Other LiteraryWorm titles show sample pages."]}, {"heading": "Can I read my own books?", "paragraphs": ["Yes. In My Library → Uploads, add EPUBs you own that have no DRM: up to 20 at a time, each up to 50 MB (a profile keeps up to 50). For example, buy a book that the publisher sells DRM-free on Google Play Books, download its EPUB from your Google Play Books library, then upload it to LiteraryWorm. Many publishers and stores sell DRM-free books, and public-domain EPUBs are free from Project Gutenberg and Standard Ebooks.", "Your upload opens in the reader with your place, bookmarks and highlights, and once you've opened it on a device, it keeps working there if your connection drops. Books with DRM can't be uploaded, and removing DRM to upload a book isn't allowed (see the Terms of Service)."]}, {"heading": "Reading and listening", "paragraphs": ["Open a book from its page with Read or Listen. Your place is shared between the two and across your devices. The mini-player keeps a book playing while you browse, and its controls also work from your lock screen and headphones.", "To read or listen without a connection, choose Read offline on a public-domain book's page. Each book's page has My journal for private, dated notes only you see; they're exported with your highlights from My Library → Notes. Words you keep from the dictionary come back for review in My words, after 1, 3, 7, 14, 30 and 60 days while you know them. Your reading streak has two rest days a month, used automatically when you miss a day."]}, {"heading": "Your account and household", "paragraphs": ["Each person at home can have their own profile, with its own library and recommendations. Lock a profile with a PIN, set daily limits for younger readers, and change your plan, password or emails in Account. You can cancel or pause online at any time.", "In Account → Sign-in you can add a passkey to log in with your face, fingerprint, screen lock or a security key instead of your password, and rename or remove passkeys you no longer use.", "A Kids profile can ask for a book that isn't on its shelf; a grown-up says yes or no in Account → Family with the account password, and a yes opens that one book for that profile.", "Your plan includes some hours of audiobooks a month for the household (Premium has no limit) and a number of devices that can keep books offline. Account → Plan and billing shows how much you've used this month and which devices hold offline places, and lets you free one.", "To hear when a book you set Remind me on comes out, turn on Notifications on this device in Account → Preferences. Once it's on, choose there which notifications you get: books you're waiting for, club meetings, new club posts up to your chapter, an evening streak nudge, and answers to Kids book requests. On iPhone and iPad, add LiteraryWorm to your Home Screen first (Share, then Add to Home Screen) and turn them on in the app.", "Grown-up and teen profiles can put a book on the family shelf from its page; it shows on Home for everyone at home, and Kids profiles see only the books their rating already allows.", "On a book club's page, Where everyone is shows the chapter each member has reached, for members who turn on Show my place to this club; it's off until you turn it on.", "Under a club's discussion, Shared highlights shows passages members marked in the book; ones from chapters you haven't reached stay hidden until you choose to see them. Share one of yours from the list there, with or without its note, and stop sharing it whenever you like.", "My Library → Smart lists fill themselves: Almost there (past halfway), Waiting for you (started, not opened for 30 days), From authors you follow and Loved it.", "A book's page shows Your time with this book once you've read or listened to it: time spent, the days, your pace through it and your biggest days.", "In the player (and the mini-player's More), Previously… catches you up on a public-domain book from the second chapter on: the story so far and the last chapter, written by AI from the chapters before yours only.", "My Library → Notes has Review for highlights: each comes back the day after you make it, then after 1, 3, 7, 14, 30 and 60 days while it still matters, up to 10 a day, and Home says when some are due.", "On a book's page, Reading plan lets you pick a day to finish by: it works out about how many minutes (at your own pace) or pages a day get you there, and says whether you're on track, ahead or behind; Home lists your plans.", "When you buy a gift on Gifts, you can add up to 10 LiteraryWorm books to it (find a title, or add one of your lists); they're waiting in the recipient's library when they redeem it.", "To take your library elsewhere, choose Export for Goodreads or Export for StoryGraph in My Library: you get a CSV of your books, shelves, star ratings (Love it 5, Like it 4, Not for me 2) and dates, made on your device, to import there.", "In the reader, Display has OpenDyslexic among the fonts, and Reading guide: a reading ruler on one line, or line focus, which dims everything but three lines. It follows your pointer or a tap; J and K move it down or up a line.", "On an audiobook's page, Read offline has Listen offline on a schedule: this device keeps the chapter you're on and the next 1, 3, 5 or 10 as you listen, on Wi-Fi only if you like, and can remove chapters you've finished. It counts as one of your plan's offline devices."]}, {"heading": "Trouble logging in?", "paragraphs": ["If Log in or Log in with a passkey does nothing, check that your browser isn't letting LiteraryWorm access your local network. LiteraryWorm never needs that permission, and allowing it can stop logging in from working. In Chrome and Edge, select the icon beside the address, choose Site settings, set Local network access to Block, then reload the page and log in again. If your browser asks whether LiteraryWorm can find devices on your local network, choose Block.", "Still stuck? Try a private or incognito window. If that works, a browser extension or something saved in your usual window is in the way. Otherwise, email support@literaryworm.com with your device and browser."]}, {"heading": "Book clubs on your own books", "paragraphs": ["A club can read a LiteraryWorm title or a book you uploaded, such as a DRM-free EPUB you bought. When you start a club in My Library → Clubs, choose LiteraryWorm books or My uploads under Book from, then find the book by title, author or ISBN (an ISBN is looked up on Google Books and matched by title and author). Sort the list by title, author, numbers first or series in reading order, and filter it to one series.", "Uploads stay private, so members don't get your file. The club shows the book's title and author, and each member uploads their own copy and chooses it on the club's page (Choose your copy). Posts, where everyone is and shared highlights then follow each member's place in their own copy, so nothing past their chapter is spoiled. An uploaded book has no recording, so there's no listening along."]}, {"heading": "Report a problem", "paragraphs": ["Tell us what you were doing, the page you were on, and your device and browser, by email to support@literaryworm.com."]}]$lw$::jsonb;
